 $real=realpath($dir);$root=realpath('C:/xampp/neuro-private/migration');if(!$real||!$root||strpos(strtolower(str_replace('\\','/',$real)),strtolower(str_replace('\\','/',$root)).'/')!==0)throw new RuntimeException('Invalid private directory');
